input.new_string:
import { getPosts } from '@/lib/api';

export default async function Home() {
  const posts = await getPosts();

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  );
}

export const revalidate = 3600; // Revalidate every 1 hour (3600 seconds)

